  window.getTithiEmoji = function(n) {
    if (n === 15) return "🌕"; // Purnima
    if (n === 30) return "🌑"; // Amavasya
    // Shukla Paksha (Waxing)
    if (n >= 1 && n <= 4) return "🌒";
    if (n >= 5 && n <= 9) return "🌓";
    if (n >= 10 && n <= 14) return "🌔";
    // Krishna Paksha (Waning)
    if (n >= 16 && n <= 19) return "🌖";
    if (n >= 20 && n <= 24) return "🌗";
    if (n >= 25 && n <= 29) return "🌘";
    return "🌑";
  };
