                    let sNak = Math.floor(getSidSun(mid) / (360/27));
                    let mNak = Math.floor(getSidMoon(mid) / (360/27));
                    let tithi = Math.floor(getTithiAngle(mid) / 12);
                    // Ravi Yoga Eval
                    let cnt = (mNak - sNak + 27) % 27 + 1;
