            let lonStart = getSidSun(t_start_day);
            let lonEnd = getSidSun(t_end_day);
            let unwrapEnd = lonEnd;
            if (unwrapEnd < lonStart) unwrapEnd += 360;
            let degStart = Math.floor(lonStart);
