            1, // 4: Saumya -> Siddha
            0, // 5: Dhwanksha -> Marana
            1, // 6: Dhwaja -> Siddha
            1, // 7: Srivatsa -> Siddha
            0, // 8: Vajra -> Marana
            0, // 9: Mudgara -> Marana
            1, // 10: Chhatra -> Siddha
            2, // 11: Mitra -> Amrita
            2, // 12: Manasa -> Amrita
            1, // 13: Padma -> Siddha
            0, // 14: Lumbaka -> Marana
            0, // 15: Utpata -> Marana
            0, // 16: Mrityu -> Marana
            0, // 17: Kana -> Marana
            2, // 18: Siddhi -> Amrita
            1, // 19: Shubha -> Siddha
            2, // 20: Amrita -> Amrita
            0, // 21: Mushala -> Marana
            0, // 22: Gada -> Marana
            2, // 23: Matanga -> Amrita
            0, // 24: Rakshasa -> Marana
            1, // 25: Chara -> Siddha
            2, // 26: Sthira -> Amrita
