                range: "MID-APRIL TO MID-JUNE (20 APR - 21 JUN)",
                color: "#F97316",
                bgImage: "https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=1200&q=80",
