                                const mSpanOd = (startCivil.getMonth() === endCivil.getMonth()) ? sMOd : `${sMOd} - ${eMOd}`;
                                const dSpanOd = `${sDOd} ${sMSOd} - ${eDOd} ${eMSOd}`;
                                fullStr = `${mSpanOd} (${dSpanOd})`;
