    const formatEndTime = (str) => {
        if (!str) return "";
        return str.replace(/^upto\s+/i, "Upto ");
    };

    // 11. Anukoola Nakshatrangal (Tarabalam favorable stars in Kerala)
    const rawGoodNaks = b.taraChandra?.tarabalam?.[0]?.items || [];
