function getInitialLang() {
    try {
        const params = new URLSearchParams(window.location.search);
        const queryLang = params.get('lang');
        if (queryLang) {
            const l = queryLang.toLowerCase();
            if (langData[l]) return l;
            if (langUrlMap[l]) return langUrlMap[l];
        }
        const savedLang = localStorage.getItem('panchangAppLang');
        if (savedLang) {
            const l = savedLang.toLowerCase();
            if (langData[l]) return l;
            if (langUrlMap[l]) return langUrlMap[l];
        }
    } catch (e) {
        console.warn('Error reading initial language', e);
    }
    return 'en';
}

