const isWideScript = (lang) => ['ml', 'ta', 'te', 'kn'].includes(lang);

const toLocalDigits = (strOrNum, lang) => {
    if (strOrNum == null) return "";
    const s = String(strOrNum);
    const nums = langData[lang]?.nums;
    if (!nums || nums.length !== 10) return s;
    return s.replace(/[0-9]/g, d => nums[parseInt(d, 10)] || d);
};

const formatHeaderDay = (dateObj, lang) => {
    const dIdx = dateObj.getDay();
    return (langData[lang]?.days && langData[lang].days[dIdx]) || dateObj.toLocaleDateString("en-US", { weekday: "long" });
};

const formatHeaderDate = (dateObj, lang) => {
    const mIdx = dateObj.getMonth();
    const monthName = (langData[lang]?.months && langData[lang].months[mIdx]) || dateObj.toLocaleDateString("en-US", { month: "long" });
    const dateNum = toLocalDigits(dateObj.getDate(), lang);
    const year = toLocalDigits(dateObj.getFullYear(), lang);
    return `${monthName} ${dateNum}, ${year}`;
};

const formatHeaderSubtitle = (bData, lang) => {
    if (!bData) return "";
    const t = TOP_SECTION_I18N[lang] || TOP_SECTION_I18N.en;
    const isShukla = bData.tithi?.paksha === "Shukla";
    const pakshaStr = (langData[lang]?.paksha && langData[lang].paksha[isShukla ? 0 : 1]) || bData.tithi?.paksha || "";
    const tNum = bData.tithi?.number ? ((bData.tithi.number - 1) % 30) : 0;
    const tIdx = tNum === 14 ? 14 : (tNum === 29 ? 15 : (tNum % 15));
    const tithiStr = (langData[lang]?.tithis && langData[lang].tithis[tIdx]) || bData.tithi?.name || "";
    
    let kshayaPart = "";
    if (bData.tithi?.kshaya) {
        const kNum = bData.tithi.kshaya.number || 1;
        const kIdx = kNum === 15 ? 14 : (kNum === 30 ? 15 : ((kNum - 1) % 15));
        const kName = (langData[lang]?.tithis && langData[lang].tithis[kIdx]) || bData.tithi.kshaya.name;
        const kLabel = lang === 'or' ? 'କ୍ଷୟ' : (lang === 'hi' ? 'क्षय' : 'Kshaya');
        kshayaPart = ` · ${kName} (${kLabel})`;
    }

    let solarPart = "";
    const mPrav = bData.samvatDetails?.pravishte?.match(/(\d+)\s*\((.*?)\s+Gate\)/);
    if (mPrav) {
        const day = toLocalDigits(mPrav[1], lang);
        const rashiEn = mPrav[2].trim();
        const rashiNames = ["Mesha","Vrishabha","Mithuna","Karka","Simha","Kanya","Tula","Vrishchika","Dhanu","Makara","Kumbha","Meena"];
        const rIdx = rashiNames.indexOf(rashiEn);
        const rashiStr = (rIdx >= 0 && langData[lang]?.rashis && langData[lang].rashis[rIdx]) || rashiEn;
        solarPart = ` · ${rashiStr} ${day} ${t.dayLabel}`;
    }
    return `${t.todayPrefix}: ${pakshaStr} ${tithiStr}${kshayaPart}${solarPart}`;
};

const formatBarDateLocal = (dateObj, lang) => {
    const dIdx = dateObj.getDay();
    const mIdx = dateObj.getMonth();
    const t = TOP_SECTION_I18N[lang] || TOP_SECTION_I18N.en;
    const dayName = (t.shortDays && t.shortDays[dIdx]) || ['SUN', 'MON', 'TUE', 'WED', 'THU', 'FRI', 'SAT'][dIdx];
    const monthName = (t.shortMonths && t.shortMonths[mIdx]) || ['JAN', 'FEB', 'MAR', 'APR', 'MAY', 'JUN', 'JUL', 'AUG', 'SEP', 'OCT', 'NOV', 'DEC'][mIdx];
    const rawDate = String(dateObj.getDate()).padStart(2, '0');
    const dateNum = toLocalDigits(rawDate, lang);
    const year = toLocalDigits(dateObj.getFullYear(), lang);
    return `${dayName}, ${dateNum} ${monthName} ${year}`;
};

const formatLocalTimeDisplay = (str, lang) => {
    if (!str || str === '--:--' || str === 'No Rise' || str === 'No Set') {
        const noRiseLabel = {
            en: "No Rise", hi: "उदय नहीं", or: "ଉଦୟ ନାହିଁ", bn: "উদয় নেই", mr: "उदय नाही",
            gu: "ઉદય નથી", pa: "ਚੜ੍ਹਨਾ ਨਹੀਂ", ta: "உதயமில்லை", te: "ఉదయం లేదు", kn: "ಉದಯವಿಲ್ಲ", ml: "ഉദയമില്ല", as: "উদয় নাই"
        }[lang] || "No Rise";
        const noSetLabel = {
            en: "No Set", hi: "अस्त नहीं", or: "ଅସ୍ତ ନାହିଁ", bn: "অস্ত নেই", mr: "अस्त नाही",
            gu: "અસ્ત નથી", pa: "ਡੁੱਬਣਾ ਨਹੀਂ", ta: "அஸ்தமனமில்லை", te: "అస్తమయం లేదు", kn: "ಅಸ್ತವಿಲ್ಲ", ml: "ಅಸ್ತಮಯമില്ല", as: "অস্ত নাই"
        }[lang] || "No Set";
        if (str === 'No Rise') return noRiseLabel;
        if (str === 'No Set') return noSetLabel;
        return str || '--:--';
    }
    const parts = str.split(", ");
    let timePart = toLocalDigits(parts[0], lang);
    if (parts[1]) {
        const dParts = parts[1].split(" ");
        if (dParts.length === 2) {
            const shortMonths = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
            const mIdx = shortMonths.findIndex(m => dParts[0].toLowerCase().startsWith(m.toLowerCase()));
            const mName = (mIdx >= 0 && langData[lang]?.months && langData[lang].months[mIdx]) || dParts[0];
            const dNum = toLocalDigits(dParts[1], lang);
            return `${timePart}, ${mName} ${dNum}`;
        }
        return `${timePart}, ${toLocalDigits(parts[1], lang)}`;
    }
    return timePart;
};

